import re

def merge_summaries(parts: list) -> str:
    """把多段摘要聚合成整篇摘要。
    过滤空白段；去除内容重复的段（忽略空白和标点差异）；
    用换行连接剩余段。
    """
    seen = set()
    result = []

    for part in parts:
        if not isinstance(part, str):
            continue
        part = part.strip()
        if not part:
            continue

        key = re.sub(r"[\W_]+", "", part)
        if key in seen:
            continue

        seen.add(key)
        result.append(part)

    return "\n".join(result)

